const fs = require('fs'), home = require('os').homedir()
for (const rel of process.argv.slice(2)) {
  const j = JSON.parse(fs.readFileSync(`${home}/.omniroute/call_logs/${rel}`, 'utf8'))
  const body = j.requestBody ?? j.request?.body ?? j.request ?? j
  console.log('== keys', Object.keys(j).join(','), '| body keys', Object.keys(body).join(','))
  const msgs = body.messages ?? []
  const size = (x) => JSON.stringify(x ?? '').length
  const by = {}
  for (const m of msgs) {
    const parts = Array.isArray(m.content) ? m.content : [{ type: 'text', text: m.content }]
    for (const p of parts) { const k = m.role + ':' + (p.type ?? 'text'); by[k] = (by[k] ?? 0) + size(p) }
    if (m.reasoning_content) by[m.role + ':reasoning_content'] = (by[m.role + ':reasoning_content'] ?? 0) + size(m.reasoning_content)
    if (m.tool_calls) by[m.role + ':tool_calls'] = (by[m.role + ':tool_calls'] ?? 0) + size(m.tool_calls)
  }
  console.log('messages', msgs.length, '| system', size(body.system), '| tools', size(body.tools), body.tools?.length, 'tools')
  console.log(Object.entries(by).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k}=${Math.round(v / 1000)}K`).join('  '))
}
